export function Swipe({
  swiped = {{swiped}},
  direction = "{{direction}}",
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  const offset = direction === "left" ? -70 : 70;
  return (
    <div style={{ position: "relative", width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", overflow: "hidden" }}>
      <div style={{ position: "absolute", top: 16, bottom: 40, [direction === "left" ? "right" : "left"]: 16, width: 70, borderRadius: 8, display: "grid", placeItems: "center", fontWeight: 700, color: "#241430", background: accent }}>Delete</div>
      <div className="card" style={{ position: "relative", background: "#fff", border: "1px solid #24143022", borderRadius: 8, padding: 16, textAlign: "center", color: "#241430", transform: swiped ? `translateX(${offset}px)` : "translateX(0)" }}>
        Swipe {direction} to reveal
      </div>
      <p style={{ margin: "10px 0 0" }}>{swiped ? "Revealed" : "Resting"} &mdash; a horizontal drag gesture</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .card { transition: transform ${duration}ms ease-out; }
        }
      `}</style>
    </div>
  );
}
